import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';
import ErrorBoundary from './components/common/ErrorBoundary';

// Suppress non-fatal browser permission & webcam errors globally
// so they don't show the red "Uncaught runtime errors" overlay in dev mode
const IGNORED_ERRORS = [
  'Permissions check failed',
  'Permission denied',
  'NotAllowedError',
  'NotFoundError',
  'Could not start video source',
  'getUserMedia',
  'mediaDevices',
];

const originalError = window.onerror;
window.onerror = (message, source, lineno, colno, error) => {
  if (IGNORED_ERRORS.some(e => String(message).includes(e))) return true; // suppress
  if (originalError) return originalError(message, source, lineno, colno, error);
};

const originalUnhandled = window.onunhandledrejection;
window.addEventListener('unhandledrejection', (event) => {
  if (IGNORED_ERRORS.some(e => String(event.reason?.message || event.reason).includes(e))) {
    event.preventDefault(); // suppress
  }
});

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <ErrorBoundary>
    <App />
  </ErrorBoundary>
);
